+/* packet-iperf3.c
+ *
+ * Routines for iPerf3 dissection
+ * by Daniel Mendes <dmendes@redhat.com>
+ *
+ * loosely based off iPerf2 dissector
+ * By Anish Bhatt <anish@gatech.edu>
+ *
+ * Wireshark - Network traffic analyzer
+ * By Gerald Combs <gerald@wireshark.org>
+ * Copyright 1998 Gerald Combs
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "config.h"
+#include <epan/packet.h>
+#include <wsutil/str_util.h> // for plurality()
+#include <inttypes.h>
+
+void proto_register_iperf3(void);
+void proto_reg_handoff_iperf3(void);
+
+static float iperf3_time(tvbuff_t *, uint32_t);
+
+static int proto_iperf3 = -1;
+
+static int hf_iperf3_sequence = -1;
+static int hf_iperf3_sec = -1;
+static int hf_iperf3_usec = -1;
+static int hf_iperf3_udp_init_msg = -1;
+static int hf_iperf3_state = -1;
+static int hf_iperf3_prejson = -1;
+static int hf_iperf3_cookie = -1;
+static int hf_iperf3_json = -1;
+static int hf_iperf3_payload = -1;
+
+static int ett_iperf3 = -1;
+static int ett_time = -1;
+
+static dissector_handle_t iperf3_handle_tcp = NULL;
+static dissector_handle_t iperf3_handle_udp = NULL;
+
+#define TEST_START 1
+#define TEST_RUNNING 2
+#define RESULT_REQUEST 3 /* not used */
+#define TEST_END 4
+#define STREAM_BEGIN 5    /* not used */
+#define STREAM_RUNNING 6  /* not used */
+#define STREAM_END 7      /* not used */
+#define ALL_STREAMS_END 8 /* not used */
+#define PARAM_EXCHANGE 9
+#define CREATE_STREAMS 10
+#define SERVER_TERMINATE 11
+#define CLIENT_TERMINATE 12
+#define EXCHANGE_RESULTS 13
+#define DISPLAY_RESULTS 14
+#define IPERF_START 15
+#define IPERF_DONE 16
+#define ACCESS_DENIED (-1)
+#define SERVER_ERROR (-2)
+
+static char *iperf3_statuscodes[] = {
+    "__unused__",
+    "TEST_START",
+    "TEST_RUNNING",
+    "RESULT_REQUEST",
+    "TEST_END",
+    "STREAM_BEGIN",
+    "STREAM_RUNNING",
+    "STREAM_END",
+    "ALL_STREAMS_END",
+    "PARAM_EXCHANGE",
+    "CREATE_STREAMS",
+    "SERVER_TERMINATE",
+    "CLIENT_TERMINATE",
+    "EXCHANGE_RESULTS",
+    "DISPLAY_RESULTS",
+    "IPERF_START",
+    "IPERF_DONE",
+}; // used for reverse mapping from number to code
+static char *iperf3_errorcodes[] = {
+    "__unused__",
+    "ACCESS_DENIED",
+    "SERVER_ERROR"
+};
+
+#define IPERF3_UDP_HDR_SIZE 12
+#define IPERF3_INIT_UDP_MSG_SIZE 4
+#define COOKIE_SIZE (37)
+
+#define UDP_CONNECT_MSG 0x36373839
+#define UDP_CONNECT_REPLY 0x39383736
+#define LEGACY_UDP_CONNECT_MSG 0x075bcd15
+#define LEGACY_MSG_OPPOSITE_ENDIAN 0x15cd5b07   // iperf3 doesn't htonl() convert either the MSG or REPLY
+#define LEGACY_UDP_CONNECT_REPLY 0x3ade68b1     // so we must accept either endian repr. luckily current msg and reply are
+#define LEGACY_REPLY_OPPOSITE_ENDIAN 0xb168de3a // already opposites. this is also why we can't distinguish msg from reply
+
+#define bytes2bits(num) ((num)*8)
+
+#define DEFINE_CONTROL_PREFACE(protocol)                                                            \
+    static void control_preface_##protocol(packet_info *pinfo)                                      \
+    {                                                                                               \
+        col_set_str(pinfo->cinfo, COL_PROTOCOL, "iPerf3");                                          \
+        col_clear(pinfo->cinfo, COL_INFO);                                                          \
+        col_append_ports(pinfo->cinfo, COL_INFO, PT_##protocol, pinfo->srcport, pinfo->destport);   \
+        col_append_str(pinfo->cinfo, COL_INFO, " ");                                                \
+    }
+
+DEFINE_CONTROL_PREFACE(TCP) /* invoke as control_preface_TCP(pinfo) */
+DEFINE_CONTROL_PREFACE(UDP)
+
+static int
+dissect_iperf3_tcp(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    proto_item *ti  = proto_tree_add_item(tree, proto_iperf3, tvb, 0, -1, ENC_NA);
+    proto_tree *iperf3_tree = proto_item_add_subtree(ti, ett_iperf3);
+    uint32_t nbytes = tvb_reported_length(tvb);
+
+    /*this is fragile for packet lengths of 1,4,& 37 but those would be strangely small user choices
+                maybe we add "X bytes: most likely interpreted as: "*/
+    /************************************ state ID ************************************************************/
+    if (nbytes == 1) {
+        int8_t state_code = tvb_get_bits8(tvb, 0, 8);
+        if (state_code < -2 || state_code > 16)
+            goto payload_label;
+        const char *msg = (state_code >= 0) ? iperf3_statuscodes[state_code] : iperf3_errorcodes[state_code * -1];
+        control_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO, "%s(%" PRIi8 ")", msg, state_code);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_state, tvb, 0, nbytes, ENC_NA);
+    /************************************ pre-JSON ************************************************************/
+    } else if (nbytes == 4) {
+        uint64_t json_size = tvb_get_bits64(tvb, 0, bytes2bits(4), ENC_BIG_ENDIAN);
+
+        control_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO, "Next message is JSON of this length: %" PRIu64 "", json_size);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_prejson, tvb, 0, nbytes, ENC_NA);
+
+    /***************************************** cookie **********************************************************/
+    } else if (nbytes == COOKIE_SIZE) {
+        char cookie[COOKIE_SIZE]; /* no extra room b/c already null terminated */
+        tvb_get_raw_bytes_as_string(tvb, 0, &cookie[0], COOKIE_SIZE);
+
+        control_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO, "cookie: \"%s\"", cookie);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_cookie, tvb, 0, nbytes, ENC_NA);
+
+    /******************************************* JSON ***********************************************************/
+    } else if (tvb_get_bits16(tvb, 0, 16, ENC_BIG_ENDIAN) == 0x7b22 && tvb_get_bits8(tvb, bytes2bits(nbytes - 1), 8) == 0x7d) {
+        /* hueristic: iperf3 json begins with {" and ends with } */
+
+        char *buffer = malloc(nbytes + 1); /*need room for the added null terminator*/
+        tvb_get_raw_bytes_as_string(tvb, 0, &buffer[0], nbytes + 1);
+
+        control_preface_TCP(pinfo);
+        col_append_fstr(pinfo->cinfo, COL_INFO, "%s", buffer);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_json, tvb, 0, nbytes, ENC_NA);
+
+    /******************************************* PAYLOAD ********************************************************/
+    } else {
+        payload_label:
+        col_set_str(pinfo->cinfo, COL_PROTOCOL, "iPerf3");
+        proto_tree_add_bytes_format(iperf3_tree, hf_iperf3_payload, tvb, 0, -1, NULL, "Payload (%" PRIu32 "byte%s)", nbytes,
+            plurality(nbytes, "", "s"));
+    }
+
+    return nbytes;
+}
+
+static int
+dissect_iperf3_udp(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    proto_item *ti;
+    proto_tree *iperf3_tree, *time_tree;
+    uint32_t nbytes = tvb_reported_length(tvb);
+
+    /********************************* UDP CONTROL ************************************************/
+    if (nbytes == IPERF3_INIT_UDP_MSG_SIZE)
+    {
+
+        uint32_t init_cxn_msg = tvb_get_bits32(tvb, 0, 32, ENC_HOST_ENDIAN);
+        if (init_cxn_msg != UDP_CONNECT_MSG &&
+                init_cxn_msg != UDP_CONNECT_REPLY &&
+                init_cxn_msg != LEGACY_UDP_CONNECT_MSG &&
+                init_cxn_msg != LEGACY_MSG_OPPOSITE_ENDIAN &&
+                init_cxn_msg != LEGACY_UDP_CONNECT_REPLY &&
+                init_cxn_msg != LEGACY_REPLY_OPPOSITE_ENDIAN)
+            return 0;
+        control_preface_UDP(pinfo);
+        col_append_str(pinfo->cinfo, COL_INFO, "Establishing UDP connection...");
+
+        ti = proto_tree_add_item(tree, proto_iperf3, tvb, 0, -1, ENC_NA);
+        iperf3_tree = proto_item_add_subtree(ti, ett_iperf3);
+        proto_tree_add_item(iperf3_tree, hf_iperf3_udp_init_msg, tvb, 0, 4, ENC_BIG_ENDIAN);
+        return IPERF3_INIT_UDP_MSG_SIZE;
+    }
+
+    /******************************* UDP DATA ************************************************/
+
+    if (tvb_reported_length(tvb) < IPERF3_UDP_HDR_SIZE)
+        return 0;
+
+    uint32_t offset = 0;
+
+    col_set_str(pinfo->cinfo, COL_PROTOCOL, "iPerf3");
+    ti = proto_tree_add_item(tree, proto_iperf3, tvb, offset, -1, ENC_NA);
+    iperf3_tree = proto_item_add_subtree(ti, ett_iperf3);
+                                                                          /*empirically: no precision below 7 digits*/
+    time_tree = proto_tree_add_subtree_format(iperf3_tree, tvb, offset, 8, ett_time, &ti, "Time Sent [%.7f seconds]", iperf3_time(tvb, offset));
+
+    proto_tree_add_item(time_tree, hf_iperf3_sec, tvb, offset, 4, ENC_BIG_ENDIAN);
+    offset += 4;
+    proto_tree_add_item(time_tree, hf_iperf3_usec, tvb, offset, 4, ENC_BIG_ENDIAN);
+    offset += 4;
+
+    uint64_t maybe_sequence_num = tvb_get_bits32(tvb, bytes2bits(offset), 32, ENC_BIG_ENDIAN);   // we need to detect 32 or 64 bit sequence number.
+    if (maybe_sequence_num) {                                                                   // iperf starts sequence number at 1 not 0
+        proto_tree_add_item(iperf3_tree, hf_iperf3_sequence, tvb, offset, 4, ENC_BIG_ENDIAN);   // so... assuming you never send more than 2**32 packets
+        offset += 4;                                                                            // it works as a proxy to test if top 4 bits are all 0
+    } else {
+        proto_tree_add_item(iperf3_tree, hf_iperf3_sequence, tvb, offset, 8, ENC_BIG_ENDIAN);
+        maybe_sequence_num = tvb_get_bits64(tvb, bytes2bits(offset), 64, ENC_BIG_ENDIAN);
+        offset += 8;
+    }
+
+    proto_tree_add_bytes_format(iperf3_tree, hf_iperf3_payload, tvb, offset, offset == tvb_reported_length(tvb) ? 0 : -1, NULL,
+        "Payload (%u byte%s)", nbytes - offset, plurality(nbytes, "", "s"));
+    col_add_fstr(pinfo->cinfo, COL_INFO, "[%"PRIu64"] local time=%.7f length=%"PRIu32" bytes", maybe_sequence_num, nstime_to_sec(&pinfo->rel_ts), nbytes);
+    return nbytes;
+}
+
+static float
+iperf3_time(tvbuff_t *tvb, uint32_t offset) {
+    uint32_t seconds = tvb_get_bits32(tvb, bytes2bits(offset), 32, ENC_BIG_ENDIAN);
+    uint32_t useconds = tvb_get_bits32(tvb, bytes2bits(offset + 4), 32, ENC_BIG_ENDIAN);
+    return (seconds + (useconds / 1000000.0));
+}
+
+void proto_register_iperf3(void)
+{
+    /* Setup list of header fields */
+    static hf_register_info hf[] = {
+        // TCP
+        {&hf_iperf3_state,
+         {"State ID", "iperf3.state", FT_INT8, BASE_DEC,
+          NULL, 0, NULL, HFILL}},
+        {&hf_iperf3_prejson,
+         {"Pre-JSON length identifier", "iperf3.prejson", FT_UINT32, BASE_DEC,
+          NULL, 0, NULL, HFILL}},
+        {&hf_iperf3_cookie,
+         {"Cookie", "iperf3.cookie", FT_STRINGZ, BASE_NONE,
+          NULL, 0, NULL, HFILL}},
+        {&hf_iperf3_json,
+         {"JSON", "iperf3.json", FT_STRING, BASE_NONE,
+          NULL, 0, NULL, HFILL}},
+        // UDP
+        {&hf_iperf3_sec,
+         {"iPerf3 sec", "iperf3.sec", FT_INT32, BASE_DEC,
+          NULL, 0, NULL, HFILL}},
+        {&hf_iperf3_usec,
+         {"iPerf3 usec", "iperf3.usec", FT_UINT32, BASE_DEC,
+          NULL, 0, NULL, HFILL}},
+        {&hf_iperf3_sequence,
+         {"iPerf3 sequence", "iperf3.sequence", FT_UINT64, BASE_DEC,
+          NULL, 0, NULL, HFILL}},
+        {&hf_iperf3_udp_init_msg,
+         {"UDP initialization message", "iperf3.init_msg", FT_UINT32, BASE_HEX,
+          NULL, 0, NULL, HFILL}},
+        // PAYLOAD
+        {&hf_iperf3_payload,
+         {"Payload", "iperf3.payload", FT_BYTES, BASE_NONE,
+          NULL, 0, NULL, HFILL}},
+    };
+
+    /* Setup protocol subtree array */
+    static int *ett[] = {
+        &ett_iperf3,
+        &ett_time
+    };
+
+    /* Register the protocol name and description */
+    proto_iperf3 = proto_register_protocol("iPerf3 Speed Test", "iPerf3", "iperf3");
+
+    proto_register_field_array(proto_iperf3, hf, array_length(hf));
+    proto_register_subtree_array(ett, array_length(ett));
+
+    iperf3_handle_tcp = register_dissector("iperf3_tcp", dissect_iperf3_tcp, proto_iperf3);
+    iperf3_handle_udp = register_dissector("iperf3_udp", dissect_iperf3_udp, proto_iperf3);
+}
+
+void proto_reg_handoff_iperf3(void)
+{
+    dissector_add_uint_with_preference("tcp.port", 5201, iperf3_handle_tcp);
+    dissector_add_uint_with_preference("udp.port", 5201, iperf3_handle_udp);
+}
